package com.masroufi.app.ui.components

import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Subscription catalogue. Logos come from Simple Icons (CC0 data; the marks themselves remain their owners'
 * trademarks and are used only to identify the service). Brands that asked Simple Icons to remove their logo get a
 * neutral monogram tile instead, never a recreated mark.
 */
data class Service(
    val key: String,
    val title: String,
    /** Brand colour from Simple Icons, or null for monogram tiles (they take a palette colour). */
    val brandArgb: Long?,
    val category: Category,
    private val path: String?,
    val monogram: String? = null,
) {
    enum class Category(val categoryId: String) { STREAMING("sys_entertainment"), TELECOM("sys_bills"), SOFTWARE("sys_other_expense"), HEALTH("sys_health") }

    val color: Color? get() = brandArgb?.let { Color(it) }

    /** White logo on a 24-unit grid, parsed once on first use. */
    val logo: ImageVector? by lazy {
        path?.let {
            ImageVector.Builder(name = key, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
                .addPath(pathData = PathParser().parsePathString(it).toNodes(), fill = SolidColor(Color.White))
                .build()
        }
    }
}

